#include <string.h>

#include "common/embedded_resources.h"

// The table is generated by the build (libretro/embed.sh).
extern "C" {
struct EmbeddedResource {
    const char* path;
    const unsigned char* data;
    unsigned long size;
};
extern const struct EmbeddedResource g_embedded_resources[];
extern const unsigned long g_embedded_resource_count;
}

namespace Common {

const u8* GetEmbeddedResource(const char* path, size_t* size) {
    for (unsigned long i = 0; i < g_embedded_resource_count; i++) {
        const EmbeddedResource& resource = g_embedded_resources[i];
        if (strcmp(path, resource.path) == 0) {
            *size = resource.size;
            return resource.data;
        }
    }
    *size = 0;
    return nullptr;
}

void ForEachEmbeddedResource(const char* prefix,
                             void (*fn)(void* ctx, const char* path, const u8* data, size_t size),
                             void* ctx) {
    const size_t prefix_length = strlen(prefix);
    for (unsigned long i = 0; i < g_embedded_resource_count; i++) {
        const EmbeddedResource& resource = g_embedded_resources[i];
        if (strncmp(resource.path, prefix, prefix_length) == 0) {
            fn(ctx, resource.path, resource.data, resource.size);
        }
    }
}

} // namespace Common
